mapper.select:
select 
from app_user

order by ${q.orderBy}
limit #{q.size} offset #{q.offset}

mapper.update:
update app_user
set display_name = #{displayName},
    email        = #{email}
where id = #{id}

update app_user
set status = #{status}
where id = #{id}

update app_user
set password_hash = #{passwordHash}
where id = #{id}
